// ==========================================
// ManuMind AI - Report Generator Preprocessor
// Purpose:
// Accept dashboard OR scheduling data and
// prepare a clean payload for the LLM.
// ==========================================

const items = $input.all();

return items.map(item => {

    const body = item.json.body || {};

    const source = body.source;
    const timestamp = body.timestamp;
    const details = body.details || {};

    // Validate source
    if (source !== "dashboard" && source !== "scheduling") {
        return {
            json: {
                error: "Invalid report source. Expected dashboard or scheduling."
            }
        };
    }

    // ------------------------------------------
    // Dashboard Report
    // ------------------------------------------

    if (source === "dashboard") {

        const summary = details.summary || {};

        return {
            json: {
                reportType: "dashboard",
                generatedAt: timestamp,

                data: {
                    summary: {
                        totalProduction: summary.totalProduction,
                        totalDefects: summary.totalDefects,
                        averageUtilization: summary.averageUtilization,
                        bestMachine: summary.bestMachine,
                        bestShift: summary.bestShift
                    },

                    productionTrend: details.productionTrend || [],

                    machineUtilization: details.machineUtilization || [],

                    defectAnalysis: details.defectAnalysis || [],

                    shiftPerformance: details.shiftPerformance || []
                }
            }
        };
    }

    // ------------------------------------------
    // Scheduling Report
    // ------------------------------------------

    if (source === "scheduling") {

        const summary = details.summary || {};

        return {
            json: {
                reportType: "scheduling",
                generatedAt: timestamp,

                data: {
                    summary: {
                        productionTarget: summary.productionTarget,
                        maximumPossibleProduction:
                            summary.maximumPossibleProduction,
                        remainingUnits: summary.remainingUnits,
                        capacityStatus: summary.capacityStatus,
                        scheduleStartTime: summary.scheduleStartTime,
                        estimatedCompletion:
                            summary.estimatedCompletion,
                        deadline: summary.deadline,
                        deadlineStatus:
                            summary.deadlineStatus,
                        totalMachinesUsed:
                            summary.totalMachinesUsed,
                        estimatedDurationHours:
                            summary.estimatedDurationHours
                    },

                    schedule: (details.schedule || []).map(task => ({
                        machine: task.machine,
                        shift: task.shift,
                        unitsPerHour: task.unitsPerHour,
                        allocatedUnits: task.allocatedUnits,
                        startTime: task.startTime,
                        endTime: task.endTime,
                        estimatedHours: task.estimatedHours
                    })),

                    insights: details.insights || []
                }
            }
        };
    }

});

// ==========================================
// ManuMind AI - PDF Report HTML Preprocessor
// Purpose:
// Parse Gemini's structured report JSON,
// generate a complete HTML document,
// and send the ready-to-render HTML
// to the PDF Generator.
// ==========================================

const items = $input.all();

if (!items.length) {
    return [{
        json: {
            error: "No input received from Gemini."
        }
    }];
}

// ------------------------------------------
// Get Gemini response
// ------------------------------------------

const response = items[0]?.json?.response;

if (!response) {
    return [{
        json: {
            error: "Gemini response not found."
        }
    }];
}

// ------------------------------------------
// Parse Gemini JSON
// ------------------------------------------

let report;

try {

    // Remove markdown code fences if Gemini adds them
    const cleanedResponse = String(response)
        .replace(/^```json\s*/i, "")
        .replace(/^```\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();

    report = JSON.parse(cleanedResponse);

} catch (error) {

    return [{
        json: {
            error: "Unable to parse Gemini report JSON.",
            details: error.message
        }
    }];
}

// ------------------------------------------
// Validate report
// ------------------------------------------

if (!report || !report.report) {
    return [{
        json: {
            error: "Invalid report structure from Gemini."
        }
    }];
}

const data = report.report;

// ------------------------------------------
// HTML escape function
// Prevents special characters from
// breaking the HTML.
// ------------------------------------------

function escapeHtml(value) {

    if (value === null || value === undefined) {
        return "";
    }

    return String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");
}

// ------------------------------------------
// Basic report information
// ------------------------------------------

const title =
    data.title ||
    "ManuMind AI Manufacturing Report";

const reportType =
    data.reportType ||
    "Manufacturing Report";

const generatedAt =
    data.generatedAt ||
    new Date().toISOString();

const description =
    data.description ||
    "";

const executiveSummary =
    data.executiveSummary ||
    "";

const conclusion =
    data.conclusion ||
    "";

// ------------------------------------------
// KPI HTML
// ------------------------------------------

const kpis = Array.isArray(data.kpis)
    ? data.kpis
    : [];

const kpiRows = kpis.map(kpi => {

    return `
        <tr>
            <td>${escapeHtml(kpi.label)}</td>
            <td><strong>${escapeHtml(kpi.value)}</strong></td>
            <td>${escapeHtml(kpi.unit)}</td>
            <td>${escapeHtml(kpi.status)}</td>
        </tr>
    `;

}).join("");

// ------------------------------------------
// Detailed Sections HTML
// ------------------------------------------

const sections = Array.isArray(data.sections)
    ? data.sections
    : [];

const sectionsHtml = sections.map(section => {

    const details = Array.isArray(section.details)
        ? section.details
        : [];

    const detailsHtml = details.map(detail => `
        <li>${escapeHtml(detail)}</li>
    `).join("");

    return `
        <div class="section">

            <h3>${escapeHtml(section.title)}</h3>

            <p class="section-summary">
                ${escapeHtml(section.summary)}
            </p>

            ${
                details.length > 0
                ? `<ul>${detailsHtml}</ul>`
                : ""
            }

        </div>
    `;

}).join("");

// ------------------------------------------
// Tables HTML
// ------------------------------------------

const tables = Array.isArray(data.tables)
    ? data.tables
    : [];

const tablesHtml = tables.map(table => {

    const columns = Array.isArray(table.columns)
        ? table.columns
        : [];

    const rows = Array.isArray(table.rows)
        ? table.rows
        : [];

    const headerHtml = columns.map(column => `
        <th>${escapeHtml(column)}</th>
    `).join("");

    const rowsHtml = rows.map(row => {

        const cells = Array.isArray(row)
            ? row.map(cell => `
                <td>${escapeHtml(cell)}</td>
            `).join("")
            : "";

        return `<tr>${cells}</tr>`;

    }).join("");

    return `
        <h3 class="table-title">
            ${escapeHtml(table.title)}
        </h3>

        <table class="data-table">

            <thead>
                <tr>
                    ${headerHtml}
                </tr>
            </thead>

            <tbody>
                ${rowsHtml}
            </tbody>

        </table>
    `;

}).join("");

// ------------------------------------------
// Insights HTML
// ------------------------------------------

const insights = Array.isArray(data.insights)
    ? data.insights
    : [];

const insightsHtml = insights.map(insight => `
    <li>${escapeHtml(insight)}</li>
`).join("");

// ------------------------------------------
// Recommendations HTML
// ------------------------------------------

const recommendations = Array.isArray(data.recommendations)
    ? data.recommendations
    : [];

const recommendationsHtml = recommendations.map(recommendation => `
    <li>${escapeHtml(recommendation)}</li>
`).join("");

// ------------------------------------------
// COMPLETE HTML DOCUMENT
// ------------------------------------------

const html = `
<!DOCTYPE html>

<html>

<head>

<meta charset="UTF-8">

<style>

@page {
    size: A4;
    margin: 20mm;
}

body {
    font-family: Arial, Helvetica, sans-serif;
    color: #222;
    font-size: 12px;
    line-height: 1.5;
    margin: 0;
}

.header {
    border-bottom: 3px solid #2563eb;
    padding-bottom: 15px;
    margin-bottom: 25px;
}

.title {
    font-size: 26px;
    font-weight: bold;
    color: #111827;
    margin-bottom: 5px;
}

.subtitle {
    font-size: 15px;
    color: #4b5563;
}

.meta {
    font-size: 10px;
    color: #6b7280;
    margin-top: 8px;
}

h2 {
    font-size: 18px;
    color: #1f2937;
    border-bottom: 1px solid #d1d5db;
    padding-bottom: 6px;
    margin-top: 25px;
}

h3 {
    font-size: 14px;
    color: #374151;
    margin-bottom: 6px;
}

.summary {
    background: #f3f4f6;
    border-left: 4px solid #2563eb;
    padding: 12px;
    margin: 10px 0 20px 0;
}

.section {
    margin-bottom: 18px;
    page-break-inside: avoid;
}

.section-summary {
    color: #4b5563;
}

.kpi-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    margin-bottom: 20px;
}

.kpi-table th {
    background: #2563eb;
    color: white;
    padding: 8px;
    text-align: left;
}

.kpi-table td {
    border: 1px solid #d1d5db;
    padding: 7px;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    margin-bottom: 25px;
    font-size: 10px;
    page-break-inside: auto;
}

.data-table th {
    background: #374151;
    color: white;
    padding: 7px;
    text-align: left;
}

.data-table td {
    border: 1px solid #d1d5db;
    padding: 6px;
}

.data-table tr {
    page-break-inside: avoid;
}

.table-title {
    margin-top: 20px;
}

ul {
    padding-left: 22px;
}

li {
    margin-bottom: 7px;
}

.footer {
    margin-top: 35px;
    padding-top: 10px;
    border-top: 1px solid #d1d5db;
    font-size: 9px;
    color: #6b7280;
    text-align: center;
}

</style>

</head>

<body>

<!-- HEADER -->

<div class="header">

    <div class="title">
        ${escapeHtml(title)}
    </div>

    <div class="subtitle">
        ${escapeHtml(reportType)}
    </div>

    <div class="meta">
        Generated: ${escapeHtml(generatedAt)}
    </div>

</div>


<!-- REPORT OVERVIEW -->

<h2>Report Overview</h2>

<p>
    ${escapeHtml(description)}
</p>


<!-- EXECUTIVE SUMMARY -->

<h2>Executive Summary</h2>

<div class="summary">
    ${escapeHtml(executiveSummary)}
</div>


<!-- KPIs -->

${
    kpis.length > 0
    ? `
        <h2>Key Performance Indicators</h2>

        <table class="kpi-table">

            <thead>

                <tr>
                    <th>KPI</th>
                    <th>Value</th>
                    <th>Unit</th>
                    <th>Status</th>
                </tr>

            </thead>

            <tbody>
                ${kpiRows}
            </tbody>

        </table>
    `
    : ""
}


<!-- DETAILED ANALYSIS -->

${
    sections.length > 0
    ? `
        <h2>Detailed Analysis</h2>
        ${sectionsHtml}
    `
    : ""
}


<!-- DATA TABLES -->

${
    tables.length > 0
    ? `
        <h2>Production Data</h2>
        ${tablesHtml}
    `
    : ""
}


<!-- AI INSIGHTS -->

${
    insights.length > 0
    ? `
        <h2>AI Insights</h2>

        <ul>
            ${insightsHtml}
        </ul>
    `
    : ""
}


<!-- RECOMMENDATIONS -->

${
    recommendations.length > 0
    ? `
        <h2>Recommendations</h2>

        <ul>
            ${recommendationsHtml}
        </ul>
    `
    : ""
}


<!-- CONCLUSION -->

${
    conclusion
    ? `
        <h2>Conclusion</h2>

        <div class="summary">
            ${escapeHtml(conclusion)}
        </div>
    `
    : ""
}


<!-- FOOTER -->

<div class="footer">
    ManuMind AI | Manufacturing Intelligence Platform
</div>

</body>

</html>
`;

// ------------------------------------------
// Create safe filename
// ------------------------------------------

const safeReportType = String(reportType)
    .replace(/[^a-zA-Z0-9-_]/g, "_");

const fileName =
    `ManuMind_${safeReportType}_Report.pdf`;

// ------------------------------------------
// OUTPUT
// ------------------------------------------

return [
    {
        json: {
            html: html,
            fileName: fileName,
            reportType: reportType,
            title: title
        }
    }
];

// Get PDF Generator output
const item = $input.first();

const pdfData = item.json.pdfData;
const fileName = item.json.fileName || "ManuMind_Report.pdf";
const mimeType = item.json.mimeType || "application/pdf";

if (!pdfData) {
    return [{
        json: {
            error: "PDF base64 data not found"
        }
    }];
}

// Create an explicit attachment object
return [{
    json: {
        attachment: {
            filename: fileName,
            mimeType: mimeType,
            content: pdfData
        }
    }
}];
